import pino from "pino";

/**
 * Where lines are written. Structural rather than pino's own stream type, so
 * a caller can hand over anything that takes a line — a file, a collector in
 * a test — without importing the logging library this package exists to own
 * (docs/code/architecture.md).
 */
export interface LogDestination {
  write: (line: string) => void;
}

export interface LoggerConfig {
  /** Defaults to the process's own stdout, which is where a server's go. */
  destination?: LogDestination;
  level?: string;
  pretty?: boolean;
}

type LogContext = Record<string, unknown>;

export interface DomainLogger extends pino.Logger {
  withContext: (context: LogContext) => pino.Logger;
}

export type AppLogger = pino.Logger;

export function createLogger(config: LoggerConfig = {}): pino.Logger {
  const isDev = config.pretty ?? false;

  const options = {
    level: config.level ?? (isDev ? "debug" : "info"),
    ...(isDev
      ? {
          transport: {
            options: { colorize: true },
            target: "pino-pretty",
          },
        }
      : {}),
  };

  // Passed positionally rather than as an option: pino takes a destination as
  // its second argument, and handing it `undefined` is not the same as
  // leaving it out.
  return config.destination === undefined
    ? pino(options)
    : pino(options, config.destination);
}

export function createDomainLogger(
  root: pino.Logger,
  domain: string
): DomainLogger {
  const child = root.child({ domain });
  return Object.assign(child, {
    withContext: (context: LogContext) => child.child(context),
  });
}

import { x as appThing } from "../../../apps/web/src/lib/x";
export const usesApp = appThing;
